For `src/renderer.ts`:

```typescript
import fs from 'fs';
import path from 'path';
import Handlebars from 'handlebars';
import { Page } from './types';

export class Renderer {
  private templates: Map<string, HandlebarsTemplateDelegate> = new Map();
  private templateDir: string;

  constructor(templateDir: string) {
    this.templateDir = templateDir;
    this.loadTemplates();
    this.loadPartials();
  }

  private loadTemplates(): void {
    const loadDir = (dir: string) => {
      const entries = fs.readdirSync(dir, { withFileTypes: true });
      for (const entry of entries) {
        const fullPath = path.join(dir, entry.name);
        if (entry.isDirectory()) continue; // skip partials/layouts dirs
        if (entry.name.endsWith('.hbs')) {
          const name = entry.name.replace(/\.hbs$/, '');
          const template = fs.readFileSync(fullPath, 'utf-8');
          this.templates.set(name, Handlebars.compile(template));
        }
      }
    };

    // Load templates from root and layouts directory
    loadDir(this.templateDir);
    const layoutsDir = path.join(this.templateDir, 'layouts');
    if (fs.existsSync(layoutsDir)) {
      loadDir(layoutsDir);
    }
  }

  private loadPartials(): void {
    const partialsDir = path.join(this.templateDir, 'partials');
    if (!fs.existsSync(partialsDir)) return;

    const entries = fs.readdirSync(partialsDir, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.isFile() && entry.name.endsWith('.hbs')) {
        const name = entry.name.replace(/\.hbs$/, '');
        const template = fs.readFileSync(path.join(partialsDir, entry.name), 'utf-8');
        Handlebars.registerPartial(name, template);
      }
    }
  }

  render(page: Page, allPages: Page[], siteConfig?: Record<string, unknown>): string {
    const templateName = page.frontmatter.template || 'default';
    const layoutName = page.frontmatter.layout || 'default';

    const template = this.templates.get(templateName);
    const layout = this.templates.get(layoutName);

    if (!template) {
      throw new Error(`Template "${templateName}" not found`);
    }

    const context = {
      ...page.frontmatter,
      content: page.html,
      url: page.url,
      site: siteConfig || {},
      pages: allPages,
    };

    const rendered = template(context);

    if (layout) {
      const layoutContext = {
        ...context,
        content: rendered,
      };
      return layout(layoutContext);
    }

    return rendered;
  }

  renderTags(tag: string, pages: Page[], allPages: Page[], siteConfig?: Record<string, unknown>): string {
    const tagTemplate = this.templates.get('tags') || this.templates.get('default');
    if (!tagTemplate) {
      throw new Error('No tags or default template found');
    }

    const layoutName = 'default';
    const layout = this.templates.get(layoutName);

    const context = {
      tag,
      pages,
      allPages,
      site: siteConfig || {},
      content: '',
      url: `/tags/${tag}.html`,
      title: `Tag: ${tag}`,
    };

    const rendered = tagTemplate(context);

    if (layout) {
      return layout({ ...context, content: rendered });
    }

    return rendered;
  }
}
```

Hmm, let me reconsider how layouts work. The typical pattern is:
1. Content template renders the page content into some HTML
2. Layout template wraps that HTML with headers, footers, etc.

The layout receives the content from the content template. That's the standard approach.

So in the layout template, you'd have `{{{content}}}` which gets replaced with the output of the content template.

Let me refine the render method:

```typescript
render(page, allPages, siteConfig):
  // First, render the content template
  contentHtml = contentTemplate(page, allPages, siteConfig)

  // Then, wrap with layout
  layoutHtml = layout({content: contentHtml, ...page, site: siteConfig, pages: allPages})

  return layoutHtml
```

That's what I have. Looks good.

