```typescript
import { Page, TagIndex } from './types';

export function buildTagIndices(pages: Page[]): TagIndex[] {
  const tagMap = new Map<string, Page[]>();

  for (const page of pages) {
    const tags = page.frontmatter.tags || [];
    for (const tag of tags) {
      if (!tagMap.has(tag)) {
        tagMap.set(tag, []);
      }
      tagMap.get(tag)!.push(page);
    }
  }

  const indices: TagIndex[] = [];
  for (const [tag, tagPages] of tagMap) {
    indices.push({ tag, pages: tagPages });
  }

  return indices;
}
```

For `src/rss.ts`:

```typescript
import RSS from 'rss';
import { Page } from './types';

export interface RSSConfig {
  title: string;
  description: string;
  site_url: string;
  feed_url?: string;
  language?: string;
}

export function generateRSS(pages: Page[], config: RSSConfig): string {
  const feed = new RSS({
    title: config.title,
    description: config.description,
    site_url: config.site_url,
    feed_url: config.feed_url || config.site_url + '/feed.xml',
    language: config.language || 'en',
  });

  for (const page of pages) {
    if (page.frontmatter.draft) continue;

    feed.item({
      title: page.frontmatter.title,
      description: page.html,
      url: config.site_url + page.url,
      date: page.frontmatter.date || new Date().toISOString(),
      categories: page.frontmatter.tags,
    });
  }

  return feed.xml({ indent: true });
}
```

For `src/generator.ts`:

```typescript
import fs from 'fs';
import path from 'path';
import { parseAllMarkdown } from './parser';
import { Renderer } from './renderer';
import { buildTagIndices } from './tags';
import { generateRSS } from './rss';
import { CLIOptions, Page, SiteConfig } from './types';

export class Generator {
  private options: CLIOptions;
  private renderer!: Renderer;

  constructor(options: CLIOptions) {
    this.options = options;
  }

  generate(): void {
    const { source, templates, output, drafts } = this.options;

    this.renderer = new Renderer(templates);

    // Parse all markdown files
    const pages = parseAllMarkdown(source, drafts);

    // Get non-draft pages for published content
    const publishedPages = pages.filter(p => !p.frontmatter.draft);

    // Get site config
    const siteConfig: Record<string, unknown> = {};
    if (this.options.config) {
      Object.assign(siteConfig, this.options.config);
    }

    // Create output directory
    fs.mkdirSync(output, { recursive: true });

    // Render each page
    for (const page of pages) {
      this.writePage(page, pages, siteConfig);
    }

    // Generate tag index pages
    this.generateTagPages(publishedPages, pages, siteConfig);

    // Generate RSS feed
    this.generateRSSFeed(publishedPages, siteConfig);

    // Copy static assets
    this.copyStaticAssets();
  }

  private writePage(page: Page, allPages: Page[], siteConfig: Record<string, unknown>): void {
    const html = this.renderer.render(page, allPages, siteConfig);
    const outputPath = path.join(this.options.output, page.url.replace(/^\//, ''));
    fs.mkdirSync(path.dirname(outputPath), { recursive: true });
    fs.writeFileSync(outputPath, html);
  }

  private generateTagPages(publishedPages: Page[], allPages: Page[], siteConfig: Record<string, unknown>): void {
    const tagIndices = buildTagIndices(publishedPages);

    for (const { tag, pages } of tagIndices) {
      const html = this.renderer.renderTags(tag, pages, allPages, siteConfig);
      const outputDir = path.join(this.options.output, 'tags');
      fs.mkdirSync(outputDir, { recursive: true });
      fs.writeFileSync(path.join(outputDir, `${tag}.html`), html);
    }
  }

  private generateRSSFeed(publishedPages: Page[], siteConfig: Record<string, unknown>): void {
    if (!siteConfig.url) return;

    const config = {
      title: (siteConfig.title as string) || 'My Site',
      description: (siteConfig.description as string) || '',
      site_url: siteConfig.url as string,
    };

    const rss = generateRSS(publishedPages, config);
    fs.writeFileSync(path.join(this.options.output, 'feed.xml'), rss);
  }

  private copyStaticAssets(): void {
    const sourceDir = this.options.source;

    const copyDir = (dir: string) => {
      const entries = fs.readdirSync(dir, { withFileTypes: true });
      for (const entry of entries) {
        const srcPath = path.join(dir, entry.name);
        const relativePath = path.relative(sourceDir, srcPath);
        const destPath = path.join(this.options.output, relativePath);

        if (entry.isDirectory()) {
          // Skip hidden dirs
          if (entry.name.startsWith('.')) continue;
          fs.mkdirSync(destPath, { recursive: true });
          copyDir(srcPath);
        } else if (!entry.name.endsWith('.md')) {
          fs.copyFileSync(srcPath, destPath);
        }
      }
    };

    copyDir(sourceDir);
  }
}
```

For the dev server with live reload, `src/server.ts`:

```typescript
import http from 'http';
import fs from 'fs';
import path from 'path';
import { WebSocketServer, WebSocket } from 'ws';
import chokidar from 'chokidar';
import { Generator } from './generator';
import { CLIOptions } from './types';

const RELOAD_SCRIPT = `
<script>
(function() {
  var ws = new WebSocket('ws://' + location.host + '/__livereload');
  ws.onmessage = function(msg) {
    if (msg.data === 'reload') {
      location.reload();
    }
  };
  ws.onclose = function() {
    console.log('Live reload disconnected, attempting reconnect...');
    setTimeout(function() {
      location.reload();
    }, 2000);
  };
})();
</script>
`;

export function startDevServer(options: CLIOptions): void {
  const generator = new Generator(options);
  generator.generate();

  let wsClients: WebSocket[] = [];

  const server = http.createServer((req, res) => {
    if (!req.url) {
      res.writeHead(500);
      res.end();
      return;
    }

    if (req.url === '/__livereload') {
      return; // handled by WebSocket upgrade
    }

    let filePath = path.join(options.output, req.url === '/' ? '/index.html' : req.url);

    if (!fs.existsSync(filePath) || fs.statSync(filePath).isDirectory()) {
      filePath = path.join(options.output, 'index.html');
    }

    if (!fs.existsSync(filePath)) {
      res.writeHead(404);
      res.end('Not found');
      return;
    }

    let content = fs.readFileSync(filePath, 'utf-8');

    if (filePath.endsWith('.html')) {
      content = injectReloadScript(content);
    }

    const mimeTypes: Record<string, string> = {
      '.html': 'text/html',
      '.css': 'text/css',
      '.js': 'application/javascript',
      '.json': 'application/json',
      '.png': 'image/png',
      '.jpg': 'image/jpeg',
      '.svg': 'image/svg+xml',
      '.xml': 'application/xml',
    };

    const ext = path.extname(filePath);
    res.writeHead(200, {
      'Content-Type': mimeTypes[ext] || 'text/plain',
      'Content-Length': Buffer.byteLength(content),
    });
    res.end(content);
  });

  const wss = new WebSocketServer({ server });

  wss.on('connection', (ws) => {
    wsClients.push(ws);
    ws.on('close', () => {
      wsClients = wsClients.filter(c => c !== ws);
    });
  });

  function reloadClients(): void {
    generator.generate();
    for (const client of wsClients) {
      if (client.readyState === WebSocket.OPEN) {
        client.send('reload');
      }
    }
  }

  // Watch for file changes
  const watcher = chokidar.watch([options.source, options.templates], {
    ignoreInitial: true,
    awaitWriteFinish: {
      stabilityThreshold: 100,
      pollInterval: 50,
    },
  });

  let debounceTimer: NodeJS.Timeout;
  watcher.on('all', (event, filePath) => {
    console.log(`[${event}] ${filePath}`);
    clearTimeout(debounceTimer);
    debounceTimer = setTimeout(reloadClients, 100);
  });

  server.listen(options.port, () => {
    console.log(`Dev server running at http://localhost:${options.port}`);
  });
}

function injectReloadScript(html: string): string {
  if (html.includes('</body>')) {
    return html.replace('</body>', RELOAD_SCRIPT + '</body>');
  }
  return html + RELOAD_SCRIPT;
}
```

