```typescript
import { Command } from 'commander';
import { CLIOptions } from './types';

export function parseArgs(argv: string[]): CLIOptions {
  const program = new Command();

  program
    .name('static-gen')
    .description('Static site generator from Markdown files')
    .version('1.0.0');

  program
    .command('build')
    .description('Build the static site')
    .requiredOption('-s, --source <path>', 'Source directory of Markdown files')
    .requiredOption('-t, --templates <path>', 'Templates directory')
    .requiredOption('-o, --output <path>', 'Output directory')
    .option('-d, --drafts', 'Include draft pages')
    .action((opts) => {
      Object.assign(options, opts);
      options.command = 'build';
    });

  program
    .command('serve')
    .description('Start development server with live reload')
    .requiredOption('-s, --source <path>', 'Source directory of Markdown files')
    .requiredOption('-t, --templates <path>', 'Templates directory')
    .requiredOption('-o, --output <path>', 'Output directory')
    .option('-p, --port <number>', 'Port to listen on', '3000')
    .option('-d, --drafts', 'Include draft pages')
    .action((opts) => {
      Object.assign(options, opts);
      options.command = 'serve';
    });

  const options: Partial<CLIOptions & { command: string }> = {};
  program.parse(argv);

  return {
    source: options.source || '.',
    templates: options.templates || './templates',
    output: options.output || './dist',
    port: parseInt(options.port || '3000', 10),
    drafts: options.drafts || false,
  };
}
