import { describe, it, expect } from 'vitest';
import { parseMarkdownFile, parseAllMarkdown } from '../src/parser';
import path from 'path';

const FIXTURES = path.join(__dirname, 'fixtures', 'source');

describe('parseMarkdownFile', () => {
  it('parses frontmatter title', () => {
    const page = parseMarkdownFile(path.join(FIXTURES, 'post-one.md'), FIXTURES);
    expect(page.frontmatter.title).toBe('First Post');
  });

  it('parses frontmatter date', () => {
    const page = parseMarkdownFile(path.join(FIXTURES, 'post-one.md'), FIXTURES);
    expect(page.frontmatter.date).toBe('2024-01-15');
  });

  it('parses frontmatter tags as array', () => {
    const page = parseMarkdownFile(path.join(FIXTURES, 'post-one.md'), FIXTURES);
    expect(page.frontmatter.tags).toEqual(['tech', 'javascript']);
  });

  it('parses draft flag', () => {
    const page = parseMarkdownFile(path.join(FIXTURES, 'draft-post.md'), FIXTURES);
    expect(page.frontmatter.draft).toBe(true);
  });

  it('parses template field', () => {
    const page = parseMarkdownFile(path.join(FIXTURES, 'post-one.md'), FIXTURES);
    expect(page.frontmatter.template).toBe('post');
  });

  it('converts markdown to HTML', () => {
    const page = parseMarkdownFile(path.join(FIXTURES, 'post-one.md'), FIXTURES);
    expect(page.html).toContain('<h1>First Post</h1>');
    expect(page.html).toContain('<strong>bold</strong>');
  });

  it('generates correct URL from file path', () => {
    const page = parseMarkdownFile(path.join(FIXTURES, 'post-one.md'), FIXTURES);
    expect(page.url).toBe('/post-one.html');
  });

  it('preserves raw markdown content', () => {
    const page = parseMarkdownFile(path.join(FIXTURES, 'post-one.md'), FIXTURES);
    expect(page.content).toContain('# First Post');
    expect(page.content).toContain('**bold**');
  });

  it('assigns title from filename when not in frontmatter', () => {
    const filePath = path.join(FIXTURES, 'post-two.md');
    const page = parseMarkdownFile(filePath, FIXTURES);
    expect(page.frontmatter.title).toBe('Second Post');
  });

  it('highlights code blocks', () => {
    const page = parseMarkdownFile(path.join(FIXTURES, 'post-two.md'), FIXTURES);
    expect(page.html).toContain('hljs');
    expect(page.html).toContain('language-javascript');
  });
});

describe('parseAllMarkdown', () => {
  it('finds all markdown files in source directory', () => {
    const pages = parseAllMarkdown(FIXTURES, true);
    expect(pages.length).toBeGreaterThanOrEqual(3);
  });

  it('filters out draft pages when includeDrafts is false', () => {
    const pages = parseAllMarkdown(FIXTURES, false);
    const drafts = pages.filter(p => p.frontmatter.draft);
    expect(drafts.length).toBe(0);
  });

  it('includes draft pages when includeDrafts is true', () => {
    const pages = parseAllMarkdown(FIXTURES, true);
    const drafts = pages.filter(p => p.frontmatter.draft);
    expect(drafts.length).toBe(1);
    expect(drafts[0].frontmatter.title).toBe('Draft Post');
  });

  it('sorts pages by date descending', () => {
    const pages = parseAllMarkdown(FIXTURES, true);
    const dates = pages
      .filter(p => p.frontmatter.date)
      .map(p => new Date(p.frontmatter.date!).getTime());

    expect(dates.length).toBeGreaterThanOrEqual(2);
    for (let i = 1; i < dates.length; i++) {
      expect(dates[i]).toBeLessThanOrEqual(dates[i - 1]);
    }
  });

  it('handles pages without date by placing them at end', () => {
    const pages = parseAllMarkdown(FIXTURES, true);
    const lastPage = pages[pages.length - 1];
    expect(lastPage.frontmatter.date).toBeUndefined();
  });
});

import { describe, it, expect, beforeEach } from 'vitest';
import { Renderer } from '../src/renderer';
import { Page } from '../src/types';
import path from 'path';

const TEMPLATES = path.join(__dirname, 'fixtures', 'templates');

function makePage(overrides: Partial<Page> & { frontmatter: Record<string, unknown> }): Page {
  return {
    path: 'test.md',
    url: '/test.html',
    content: '# Hello',
    html: '<h1>Hello</h1>',
    ...overrides,
    frontmatter: { title: 'Test', ...overrides.frontmatter } as Page['frontmatter'],
  };
}

describe('Renderer', () => {
  let renderer: Renderer;

  beforeEach(() => {
    renderer = new Renderer(TEMPLATES);
  });

  it('renders a page using the specified template', () => {
    const page = makePage({
      frontmatter: { title: 'My Post', date: '2024-01-01', template: 'post' },
    });

    const result = renderer.render(page, [page]);
    expect(result).toContain('<h1>My Post</h1>');
    expect(result).toContain('<h1>Hello</h1>');
  });

  it('renders page content as raw HTML', () => {
    const page = makePage({
      frontmatter: { title: 'Rich Post', template: 'post' },
      html: '<p><strong>Bold</strong> and <em>italic</em></p>',
    });

    const result = renderer.render(page, [page]);
    expect(result).toContain('<strong>Bold</strong>');
    expect(result).toContain('<em>italic</em>');
  });

  it('applies default layout wrapping', () => {
    const page = makePage({
      frontmatter: { title: 'Test', template: 'post' },
    });

    const result = renderer.render(page, [page]);
    expect(result).toContain('<!DOCTYPE html>');
    expect(result).toContain('<html lang="en">');
    expect(result).toContain('<main>');
    expect(result).toContain('</html>');
  });

  it('uses custom layout when specified in frontmatter', () => {
    const page = makePage({
      frontmatter: { title: 'Test', template: 'post', layout: 'default' },
    });

    const result = renderer.render(page, [page]);
    expect(result).toContain('<main>');
  });

  it('includes partials (header and footer) in rendered output', () => {
    const page = makePage({
      frontmatter: { title: 'Test', template: 'post' },
    });

    const result = renderer.render(page, [page]);
    expect(result).toContain('Home');
    expect(result).toContain('About');
    expect(result).toContain('Site Footer');
  });

  it('renders tags for a page', () => {
    const page = makePage({
      frontmatter: { title: 'Tagged Post', tags: ['tech', 'js'], template: 'post' },
    });

    const result = renderer.render(page, [page]);
    expect(result).toContain('/tags/tech.html');
    expect(result).toContain('/tags/js.html');
  });

  it('makes all pages available in template context', () => {
    const post1 = makePage({
      frontmatter: { title: 'Post One', date: '2024-01-01', template: 'index' },
      url: '/post-one.html',
    });
    const post2 = makePage({
      frontmatter: { title: 'Post Two', date: '2024-06-01', template: 'index' },
      url: '/post-two.html',
    });

    const result = renderer.render(post1, [post1, post2]);
    expect(result).toContain('Post One');
    expect(result).toContain('Post Two');
    expect(result).toContain('/post-one.html');
    expect(result).toContain('/post-two.html');
  });

  it('throws when template is not found', () => {
    const page = makePage({
      frontmatter: { title: 'Test', template: 'nonexistent' },
    });

    expect(() => renderer.render(page, [page])).toThrow(/Template "nonexistent" not found/);
  });

  it('renders tag index pages', () => {
    const pages = [
      makePage({
        frontmatter: { title: 'Post One', tags: ['tech'], date: '2024-01-01' },
        url: '/post-one.html',
      }),
      makePage({
        frontmatter: { title: 'Post Two', tags: ['tech'], date: '2024-02-01' },
        url: '/post-two.html',
      }),
    ];

    const allPages = [...pages];

    const result = renderer.renderTagPage('tech', pages, allPages);
    expect(result).toContain('Tag: tech');
    expect(result).toContain('Post One');
    expect(result).toContain('Post Two');
  });

  it('throws when no tags template is available', () => {
    const emptyRenderer = new Renderer(path.join(TEMPLATES, '..'));
    const page = makePage({ frontmatter: { title: 'Test' } });

    // This template dir won't have a tags template
    // Just verify that proper error is thrown for missing template
  });

  it('does not apply layout if layout template is missing', () => {
    const page = makePage({
      frontmatter: { title: 'Test', template: 'post', layout: 'nonexistent' },
    });

    const result = renderer.render(page, [page]);
    expect(result).not.toContain('<!DOCTYPE html>');
  });

  it('exposes site config in template context', () => {
    const page = makePage({
      frontmatter: { title: 'Site Test', template: 'post' },
    });

    const result = renderer.render(page, [page], { title: 'My Site' });
    expect(result).toContain('My Site');
  });
});

import { describe, it, expect } from 'vitest';
import { parseArgs } from '../src/cli';

describe('parseArgs', () => {
  it('parses build command with all required options', () => {
    const opts = parseArgs([
      'node',
      'static-gen',
      'build',
      '-s',
      './content',
      '-t',
      './templates',
      '-o',
      './dist',
    ]);

    expect(opts.command).toBe('build');
    expect(opts.source).toBe('./content');
    expect(opts.templates).toBe('./templates');
    expect(opts.output).toBe('./dist');
  });

  it('parses build command with --drafts flag', () => {
    const opts = parseArgs([
      'node',
      'static-gen',
      'build',
      '-s',
      './content',
      '-t',
      './templates',
      '-o',
      './dist',
      '--drafts',
    ]);

    expect(opts.drafts).toBe(true);
  });

  it('parses build command with -d short flag', () => {
    const opts = parseArgs([
      'node',
      'static-gen',
      'build',
      '-s',
      './content',
      '-t',
      './templates',
      '-o',
      './dist',
      '-d',
    ]);

    expect(opts.drafts).toBe(true);
  });

  it('parses serve command with required options', () => {
    const opts = parseArgs([
      'node',
      'static-gen',
      'serve',
      '-s',
      './content',
      '-t',
      './templates',
      '-o',
      './dist',
    ]);

    expect(opts.command).toBe('serve');
    expect(opts.source).toBe('./content');
    expect(opts.templates).toBe('./templates');
    expect(opts.output).toBe('./dist');
  });

  it('parses serve command with custom port', () => {
    const opts = parseArgs([
      'node',
      'static-gen',
      'serve',
      '-s',
      './content',
      '-t',
      './templates',
      '-o',
      './dist',
      '-p',
      '8080',
    ]);

    expect(opts.port).toBe(8080);
  });

  it('parses serve command with --port flag', () => {
    const opts = parseArgs([
      'node',
      'static-gen',
      'serve',
      '-s',
      './content',
      '-t',
      './templates',
      '-o',
      './dist',
      '--port',
      '9090',
    ]);

    expect(opts.port).toBe(9090);
  });

  it('defaults port to 3000 when not specified', () => {
    const opts = parseArgs([
      'node',
      'static-gen',
      'serve',
      '-s',
      './content',
      '-t',
      './templates',
      '-o',
      './dist',
    ]);

    expect(opts.port).toBe(3000);
  });

  it('defaults drafts to false', () => {
    const opts = parseArgs([
      'node',
      'static-gen',
      'build',
      '-s',
      './content',
      '-t',
      './templates',
      '-o',
      './dist',
    ]);

    expect(opts.drafts).toBe(false);
  });

  it('defaults command to build when not specified', () => {
    const opts = parseArgs([
      'node',
      'static-gen',
      '-s',
      './content',
      '-t',
      './templates',
      '-o',
      './dist',
    ]);

    // commander treats the first non-option as the command
    expect(opts.command).toBe('build');
  });
});

